int
main (int argc, char **argv)
{
  const char *progname = canonical_progname (argv[0]);
  const char *dbname;
  datum key;
  datum data;
  int flags = 0;
  GDBM_FILE dbf;
  int delim = '\t';

  while (--argc)
    {
      char *arg = *++argv;

      if (strcmp (arg, "-h") == 0)
        {
          printf ("usage: %s [-nolock] [-nommap] [-delim=CHR] DBFILE\n",
                  progname);
          exit (0);
        }
      else if (strcmp (arg, "-nolock") == 0)
        flags |= GDBM_NOLOCK;
      else if (strcmp (arg, "-nommap") == 0)
        flags |= GDBM_NOMMAP;
      else if (strcmp (arg, "-sync") == 0)
        flags |= GDBM_SYNC;
      else if (strncmp (arg, "-delim=", 7) == 0)
        delim = arg[7];
      else if (strcmp (arg, "--") == 0)
        {
          --argc;
          ++argv;
          break;
        }
      else if (arg[0] == '-')
        {
          fprintf (stderr, "%s: unknown option %s\n", progname, arg);
          exit (1);
        }
      else
        break;
    }

  if (argc != 1)
    {
      fprintf (stderr, "%s: wrong arguments\n", progname);
      exit (1);
    }
  dbname = *argv;

  dbf = gdbm_open (dbname, 0, GDBM_READER|flags, 00664, NULL);
  if (!dbf)
    {
      fprintf (stderr, "gdbm_open failed: %s\n", gdbm_strerror (gdbm_errno));
      exit (1);
    }

  key = gdbm_firstkey (dbf);
  while (key.dptr)
    {
      size_t i;
      datum nextkey;

      for (i = 0; i < key.dsize && key.dptr[i]; i++)
        {
          if (key.dptr[i] == delim || key.dptr[i] == '\\')
            fputc ('\\', stdout);
          fputc (key.dptr[i], stdout);
        }

      fputc (delim, stdout);

      data = gdbm_fetch (dbf, key);
      i = data.dsize;
      if (data.dptr[i-1] == 0)
        i--;

      fwrite (data.dptr, i, 1, stdout);
      free (data.dptr);

      fputc ('\n', stdout);

      nextkey = gdbm_nextkey (dbf, key);
      free (key.dptr);
      key = nextkey;
    }

  if (gdbm_errno != GDBM_ITEM_NOT_FOUND)
    {
      fprintf (stderr, "unexpected error: %s\n", gdbm_strerror (gdbm_errno));
      exit (1);
    }

  if (gdbm_close (dbf))
    {
      fprintf (stderr, "gdbm_close: %s; %s\n", gdbm_strerror (gdbm_errno),
               strerror (errno));
      exit (3);
    }
  exit (0);
}
